            .credentials(            
                AwsMysqlCredentialArgs.builder()
                    .username("xxxxxxxxxxx")
                    .password(dbPassword1)
                    .build(),
                AwsMysqlCredentialArgs.builder()
                    .username("xxxxxxxxxxx")
                    .password(dbPassword2)
                    .build())
            .integration(iAwsMysql.id())
            .project("backend")
            .config("dev")
            .name("DB")
            .rotationPeriodSec(2592000)
            .host("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx")
            .port(3306)
            .managingUserUsername("xxxxxxxx")
            .managingUserPassword("xxxxxxxxxxxxxxxxxxxx")
            .build(), CustomResourceOptions.builder()
                .ignoreChanges("credentials")
                .build());

    }
}
