)

func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		cfg := config.New(ctx, "")
		dbPassword1 := ""
		if param := cfg.Get("dbPassword1"); param != "" {
			dbPassword1 = param
		}
		dbPassword2 := ""
		if param := cfg.Get("dbPassword2"); param != "" {
			dbPassword2 = param
		}
		iAwsPostgres, err := integration.NewAwsPostgres(ctx, "i_aws_postgres", &integration.AwsPostgresArgs{
			Name:          pulumi.String("TF AWS Postgres"),
			AssumeRoleArn: pulumi.String("arn:aws:iam::xxxxxxxxxxxx:role/xxxxxxxxxxxxxxxx"),
			LambdaArn:     pulumi.String("arn:aws:lambda:xxxxxxxxx:xxxxxxxxxxxx:function:xxxxxxxxxxxxxxxxxxxx"),
		})
		if err != nil {
			return err
		}
		_, err = rotatedsecret.NewAwsPostgres(ctx, "rs_aws_postgres", &rotatedsecret.AwsPostgresArgs{
			Credentials: rotatedsecret.AwsPostgresCredentialArray{
				&rotatedsecret.AwsPostgresCredentialArgs{
					Username: pulumi.String("xxxxxxxxxxx"),
					Password: pulumi.String(dbPassword1),
				},
				&rotatedsecret.AwsPostgresCredentialArgs{
					Username: pulumi.String("xxxxxxxxxxx"),
					Password: pulumi.String(dbPassword2),
				},
			},
			Integration:          iAwsPostgres.ID(),
			Project:              pulumi.String("backend"),
			Config:               pulumi.String("dev"),
			Name:                 pulumi.String("DB"),
			RotationPeriodSec:    pulumi.Int(2592000),
			Host:                 pulumi.String("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"),
			Port:                 pulumi.Int(5432),
			Database:             pulumi.String("xxxxxxxx"),
			ManagingUserUsername: pulumi.String("xxxxxxxx"),
			ManagingUserPassword: pulumi.String("xxxxxxxxxxxxxxxxxxxx"),
		}, pulumi.IgnoreChanges([]string{
			"credentials",
		}))
		if err != nil {
			return err
		}
		return nil
	})
}
