```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as doppler from "@dopplerhq/pulumi-doppler";

const dopplerParameterStore = new aws.index.IamRole("doppler_parameter_store", {
    inlinePolicy: [{
        name: "doppler_secret_manager",
        policy: JSON.stringify({
            Version: "2012-10-17",
            Statement: [{
                Action: [
                    "ssm:PutParameter",
                    "ssm:LabelParameterVersion",
                    "ssm:DeleteParameter",
                    "ssm:RemoveTagsFromResource",
                    "ssm:GetParameterHistory",
                    "ssm:AddTagsToResource",
                    "ssm:GetParametersByPath",
                    "ssm:GetParameters",
                    "ssm:GetParameter",
                    "ssm:DeleteParameters",
                ],
                Effect: "Allow",
                Resource: "*",
            }],
        }),
    }],
    name: "doppler_parameter_store",
    assumeRolePolicy: JSON.stringify({
        Version: "2012-10-17",
        Statement: [{
            Effect: "Allow",
            Action: "sts:AssumeRole",
            Principal: {
                AWS: "arn:aws:iam::299900769157:user/doppler-integration-operator",
            },
            Condition: {
                StringEquals: {
                    "sts:ExternalId": "<YOUR_WORKPLACE_SLUG>",
                },
            },
        }],
    }),
});
const prod = new doppler.integration.AwsParameterStore("prod", {
    name: "Production",
    assumeRoleArn: dopplerParameterStore.arn,
});
const backendProd = new doppler.secretssync.AwsParameterStore("backend_prod", {
    integration: prod.id,
    project: "backend",
    config: "prd",
    region: "us-east-1",
    path: "/backend/",
    secureString: true,
    tags: {
        myTag: "enabled",
    },
    deleteBehavior: "leave_in_target",
});
